def find_person_to_right_of_bananas(image):
    image_patch = ImagePatch(image)
    banana_patches = image_patch.find("banana")
    person_patches = image_patch.find("person")

    # Sort the persons based on their left-most edge
    person_patches.sort(key=lambda person: person.left)

    # For each banana, find the person to its right
    for banana in banana_patches:
        for i, person in enumerate(person_patches):
            if banana.right < person.left:
                if i < len(person_patches) - 1:
                    # If the next person's left edge is greater, return the current person
                    if person_patches[i+1].left > banana.right:
                        return person_patches[i]
                else:
                    # If no person to the right of the banana, return the last person
                    return person_patches[-1]

    # If no persons found, return None
    return None

